CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role VARCHAR(24) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',failed_login_attempts INT NOT NULL DEFAULT 0,locked_until TIMESTAMP(6),last_login_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),deleted_at TIMESTAMP(6),CHECK(role IN ('ADMIN','OPERATOR','HELP_SUPPORT','CUSTOMER')),INDEX idx_users_role_status(role,status));
CREATE TABLE admin_profile(user_id BIGINT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE operator_profile(user_id BIGINT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,phone VARCHAR(30),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE support_profile(user_id BIGINT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,phone VARCHAR(30),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE customer_profile(user_id BIGINT PRIMARY KEY,customer_number VARCHAR(32) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,phone VARCHAR(30),approval_status VARCHAR(24) NOT NULL DEFAULT 'PENDING_APPROVAL',FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE zone(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE operator_zone(operator_id BIGINT NOT NULL,zone_id BIGINT NOT NULL,PRIMARY KEY(operator_id,zone_id),FOREIGN KEY(operator_id) REFERENCES operator_profile(user_id),FOREIGN KEY(zone_id) REFERENCES zone(id));
CREATE TABLE utility_service(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(16) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE connection_type(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(40) NOT NULL UNIQUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE connection(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,service_id BIGINT NOT NULL,connection_type_id BIGINT NOT NULL,zone_id BIGINT,meter_number VARCHAR(60) NOT NULL UNIQUE,address VARCHAR(500) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id),FOREIGN KEY(service_id) REFERENCES utility_service(id),FOREIGN KEY(connection_type_id) REFERENCES connection_type(id),FOREIGN KEY(zone_id) REFERENCES zone(id),INDEX idx_connection_customer(customer_id),INDEX idx_connection_zone(zone_id));
CREATE TABLE tariff_slab(id BIGINT PRIMARY KEY AUTO_INCREMENT,service_id BIGINT NOT NULL,connection_type_id BIGINT NOT NULL,range_start DECIMAL(12,3) NOT NULL,range_end DECIMAL(12,3),rate_per_unit DECIMAL(12,4) NOT NULL,fixed_charge DECIMAL(12,2) NOT NULL DEFAULT 0,tax_percent DECIMAL(6,3) NOT NULL DEFAULT 0,late_fee_percent DECIMAL(6,3) NOT NULL DEFAULT 0,due_days INT NOT NULL DEFAULT 15,effective_from DATE NOT NULL,effective_to DATE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(service_id) REFERENCES utility_service(id),FOREIGN KEY(connection_type_id) REFERENCES connection_type(id),INDEX idx_tariff_lookup(service_id,connection_type_id,effective_from));
CREATE TABLE meter_reading(id BIGINT PRIMARY KEY AUTO_INCREMENT,connection_id BIGINT NOT NULL,previous_reading DECIMAL(14,3) NOT NULL,current_reading DECIMAL(14,3) NOT NULL,reading_date DATE NOT NULL,cycle VARCHAR(7) NOT NULL,rollover BOOLEAN NOT NULL DEFAULT FALSE,remarks VARCHAR(1000),photo_path VARCHAR(500),recorded_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(connection_id) REFERENCES connection(id),FOREIGN KEY(recorded_by) REFERENCES users(id),UNIQUE KEY uq_reading_connection_cycle(connection_id,cycle));
CREATE TABLE bill(id BIGINT PRIMARY KEY AUTO_INCREMENT,bill_number VARCHAR(40) NOT NULL UNIQUE,connection_id BIGINT NOT NULL,reading_id BIGINT,cycle VARCHAR(7) NOT NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,energy_charge DECIMAL(12,2) NOT NULL DEFAULT 0,fixed_charge DECIMAL(12,2) NOT NULL DEFAULT 0,tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0,arrears DECIMAL(12,2) NOT NULL DEFAULT 0,late_fee DECIMAL(12,2) NOT NULL DEFAULT 0,adjustments DECIMAL(12,2) NOT NULL DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL,paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(24) NOT NULL DEFAULT 'GENERATED',version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(connection_id) REFERENCES connection(id),FOREIGN KEY(reading_id) REFERENCES meter_reading(id),UNIQUE KEY uq_bill_connection_cycle(connection_id,cycle),INDEX idx_bill_status_due(status,due_date));
CREATE TABLE bill_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,bill_id BIGINT NOT NULL,description VARCHAR(180) NOT NULL,quantity DECIMAL(12,3) NOT NULL DEFAULT 1,unit_rate DECIMAL(12,4) NOT NULL DEFAULT 0,amount DECIMAL(12,2) NOT NULL,FOREIGN KEY(bill_id) REFERENCES bill(id) ON DELETE CASCADE);
CREATE TABLE payment(id BIGINT PRIMARY KEY AUTO_INCREMENT,bill_id BIGINT NOT NULL,transaction_id VARCHAR(64) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,method VARCHAR(24) NOT NULL,status VARCHAR(24) NOT NULL,version BIGINT NOT NULL DEFAULT 0,paid_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(bill_id) REFERENCES bill(id),INDEX idx_payment_bill(bill_id));
CREATE TABLE receipt(id BIGINT PRIMARY KEY AUTO_INCREMENT,payment_id BIGINT NOT NULL UNIQUE,receipt_number VARCHAR(40) NOT NULL UNIQUE,file_path VARCHAR(500),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(payment_id) REFERENCES payment(id));
CREATE TABLE connection_request(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,service_id BIGINT NOT NULL,request_type VARCHAR(24) NOT NULL,details JSON,status VARCHAR(24) NOT NULL DEFAULT 'PENDING',reviewed_by BIGINT,reviewed_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id),FOREIGN KEY(service_id) REFERENCES utility_service(id),FOREIGN KEY(reviewed_by) REFERENCES users(id),INDEX idx_connection_request_status(status));
CREATE TABLE ticket(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_number VARCHAR(32) NOT NULL UNIQUE,customer_id BIGINT NOT NULL,service_id BIGINT NOT NULL,category VARCHAR(40) NOT NULL,subject VARCHAR(180) NOT NULL,description TEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'OPEN',priority VARCHAR(16) NOT NULL DEFAULT 'NORMAL',assigned_to BIGINT,due_at TIMESTAMP(6),resolved_at TIMESTAMP(6),rating TINYINT,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id),FOREIGN KEY(service_id) REFERENCES utility_service(id),FOREIGN KEY(assigned_to) REFERENCES users(id),INDEX idx_ticket_queue(status,priority,created_at));
CREATE TABLE ticket_comment(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL,author_id BIGINT NOT NULL,body TEXT NOT NULL,internal BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(ticket_id) REFERENCES ticket(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE notification(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,body VARCHAR(1000) NOT NULL,read_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_notification_user_read(user_id,read_at));
CREATE TABLE refresh_token(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMP(6) NOT NULL,revoked_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_refresh_user(user_id));
CREATE TABLE password_reset_token(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMP(6) NOT NULL,used_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(80),ip_address VARCHAR(45),old_value JSON,new_value JSON,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(actor_id) REFERENCES users(id),INDEX idx_audit_entity(entity_type,entity_id),INDEX idx_audit_created(created_at));

